Here's a complete, self-contained Account Settings screen for React Native (TypeScript), using only core RN APIs — no extra dependencies required.

```tsx
// AccountSettingsScreen.tsx
import React, { useState, useCallback } from 'react';
import {
  View,
  Text,
  Image,
  ScrollView,
  Pressable,
  Switch,
  Alert,
  StyleSheet,
  Platform,
  ActivityIndicator,
  SafeAreaView,
  StatusBar,
} from 'react-native';

// ---------- Types ----------

interface User {
  name: string;
  email: string;
  avatarUrl?: string;
}

interface AccountSettingsScreenProps {
  user: User;
  onEditProfile?: () => void;
  onNavigate?: (route: string) => void;
  onDeleteAccount: () => Promise<void>;
  onLogout?: () => void;
}

type RowProps = {
  label: string;
  value?: string;
  destructive?: boolean;
  disabled?: boolean;
  onPress?: () => void;
  rightElement?: React.ReactNode;
  isLast?: boolean;
};

// ---------- Reusable row ----------

function SettingsRow({
  label,
  value,
  destructive = false,
  disabled = false,
  onPress,
  rightElement,
  isLast = false,
}: RowProps) {
  return (
    <Pressable
      onPress={onPress}
      disabled={disabled || !onPress}
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityState={{ disabled: disabled || !onPress }}
      style={({ pressed }) => [
        styles.row,
        !isLast && styles.rowDivider,
        pressed && onPress ? styles.rowPressed : null,
      ]}
    >
      <Text
        style={[
          styles.rowLabel,
          destructive && styles.destructiveText,
          disabled && styles.disabledText,
        ]}
      >
        {label}
      </Text>

      <View style={styles.rowRight}>
        {value ? <Text style={styles.rowValue}>{value}</Text> : null}
        {rightElement}
        {onPress && !rightElement ? (
          <Text style={styles.chevron}>{'\u203A'}</Text>
        ) : null}
      </View>
    </Pressable>
  );
}

function SectionCard({ children }: { children: React.ReactNode }) {
  return <View style={styles.card}>{children}</View>;
}

// ---------- Main screen ----------

export default function AccountSettingsScreen({
  user,
  onEditProfile,
  onNavigate,
  onDeleteAccount,
  onLogout,
}: AccountSettingsScreenProps) {
  const [pushEnabled, setPushEnabled] = useState(true);
  const [emailEnabled, setEmailEnabled] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const confirmDeleteAccount = useCallback(() => {
    Alert.alert(
      'Delete account?',
      'This permanently deletes your account and all associated data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: () => {
            // Second confirmation step for an irreversible, destructive action.
            Alert.alert(
              'Are you absolutely sure?',
              `Type confirmation is not required, but this will immediately delete "${user.email}". Continue?`,
              [
                { text: 'Cancel', style: 'cancel' },
                {
                  text: 'Yes, delete my account',
                  style: 'destructive',
                  onPress: handleDeleteAccount,
                },
              ],
              { cancelable: true },
            );
          },
        },
      ],
      { cancelable: true },
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user.email]);

  const handleDeleteAccount = useCallback(async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
    } catch (err) {
      Alert.alert(
        'Couldn\u2019t delete account',
        'Something went wrong. Please check your connection and try again.',
      );
    } finally {
      setIsDeleting(false);
    }
  }, [onDeleteAccount]);

  return (
    <SafeAreaView style={styles.safeArea}>
      <StatusBar
        barStyle={Platform.OS === 'ios' ? 'dark-content' : 'default'}
      />
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        <Text style={styles.screenTitle}>Account</Text>

        {/* Profile row */}
        <Pressable
          onPress={onEditProfile}
          accessibilityRole="button"
          accessibilityLabel={`Edit profile for ${user.name}`}
          style={({ pressed }) => [
            styles.profileCard,
            pressed && styles.rowPressed,
          ]}
        >
          {user.avatarUrl ? (
            <Image source={{ uri: user.avatarUrl }} style={styles.avatar} />
          ) : (
            <View style={[styles.avatar, styles.avatarFallback]}>
              <Text style={styles.avatarInitial}>
                {user.name.charAt(0).toUpperCase()}
              </Text>
            </View>
          )}
          <View style={styles.profileInfo}>
            <Text style={styles.profileName} numberOfLines={1}>
              {user.name}
            </Text>
            <Text style={styles.profileEmail} numberOfLines={1}>
              {user.email}
            </Text>
          </View>
          <Text style={styles.chevron}>{'\u203A'}</Text>
        </Pressable>

        {/* General settings */}
        <Text style={styles.sectionHeader}>Preferences</Text>
        <SectionCard>
          <SettingsRow
            label="Push notifications"
            rightElement={
              <Switch value={pushEnabled} onValueChange={setPushEnabled} />
            }
          />
          <SettingsRow
            label="Email notifications"
            rightElement={
              <Switch value={emailEnabled} onValueChange={setEmailEnabled} />
            }
            isLast
          />
        </SectionCard>

        <Text style={styles.sectionHeader}>Account</Text>
        <SectionCard>
          <SettingsRow
            label="Change password"
            onPress={() => onNavigate?.('ChangePassword')}
          />
          <SettingsRow
            label="Privacy"
            onPress={() => onNavigate?.('Privacy')}
          />
          <SettingsRow
            label="Linked devices"
            value="3"
            onPress={() => onNavigate?.('LinkedDevices')}
            isLast
          />
        </SectionCard>

        <Text style={styles.sectionHeader}>Support</Text>
        <SectionCard>
          <SettingsRow
            label="Help center"
            onPress={() => onNavigate?.('Help')}
          />
          <SettingsRow
            label="Terms & Privacy Policy"
            onPress={() => onNavigate?.('Legal')}
            isLast
          />
        </SectionCard>

        {onLogout ? (
          <SectionCard>
            <SettingsRow label="Log out" onPress={onLogout} isLast />
          </SectionCard>
        ) : null}

        {/* Destructive action */}
        <SectionCard>
          <SettingsRow
            label={isDeleting ? 'Deleting account\u2026' : 'Delete account'}
            destructive
            disabled={isDeleting}
            onPress={confirmDeleteAccount}
            rightElement={
              isDeleting ? (
                <ActivityIndicator size="small" color="#D32F2F" />
              ) : undefined
            }
            isLast
          />
        </SectionCard>

        <Text style={styles.footerNote}>
          Deleting your account is permanent and cannot be undone.
        </Text>
      </ScrollView>
    </SafeAreaView>
  );
}

