const DESTRUCTIVE = '#D32F2F';

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: SCREEN_BG,
  },
  scrollContent: {
    paddingHorizontal: 16,
    paddingTop: Platform.OS === 'android' ? 16 : 8,
    paddingBottom: 40,
  },
  screenTitle: {
    fontSize: 28,
    fontWeight: '700',
    color: TEXT_PRIMARY,
    marginBottom: 16,
  },
  profileCard: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: CARD_BG,
    borderRadius: 14,
    padding: 14,
    marginBottom: 24,
    ...Platform.select({
      ios: {
        shadowColor: '#000',
        shadowOpacity: 0.05,
        shadowRadius: 4,
        shadowOffset: { width: 0, height: 1 },
      },
      android: {
        elevation: 1,
      },
    }),
  },
  avatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
    backgroundColor: BORDER,
  },
  avatarFallback: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarInitial: {
    fontSize: 22,
    fontWeight: '600',
    color: TEXT_SECONDARY,
  },
  profileInfo: {
    flex: 1,
    marginLeft: 14,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
    color: TEXT_PRIMARY,
  },
  profileEmail: {
    fontSize: 14,
    color: TEXT_SECONDARY,
    marginTop: 2,
  },
  sectionHeader: {
    fontSize: 13,
    fontWeight: '600',
    color: TEXT_SECONDARY,
    textTransform: 'uppercase',
    letterSpacing: 0.4,
    marginBottom: 8,
    marginLeft: 4,
  },
  card: {
    backgroundColor: CARD_BG,
    borderRadius: 14,
    marginBottom: 24,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    minHeight: 50,
    paddingHorizontal: 16,
  },
  rowDivider: {
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: BORDER,
  },
  rowPressed: {
    backgroundColor: 'rgba(0,0,0,0.04)',
  },
  rowLabel: {
    fontSize: 16,
    color: TEXT_PRIMARY,
  },
  rowRight: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  rowValue: {
    fontSize: 15,
    color: TEXT_SECONDARY,
  },
  chevron: {
    fontSize: 20,
    color: TEXT_SECONDARY,
    marginLeft: 2,
  },
  destructiveText: {
    color: DESTRUCTIVE,
  },
  disabledText: {
    opacity: 0.5,
  },
  footerNote: {
    fontSize: 12,
    color: TEXT_SECONDARY,
    textAlign: 'center',
    marginTop: -12,
    marginBottom: 8,
    paddingHorizontal: 24,
  },
});
```

Usage example (not required, just for reference):

```tsx
<AccountSettingsScreen
  user={{ name: 'Jordan Lee', email: 'jordan@example.com' }}
  onEditProfile={() => navigation.navigate('EditProfile')}
  onNavigate={(route) => navigation.navigate(route)}
  onLogout={() => auth.signOut()}
  onDeleteAccount={async () => {
    await api.deleteAccount();
    auth.signOut();
  }}
/>
```

Notes on behavior:
- **Delete account** uses a two-step native `Alert.alert` confirmation (destructive style on iOS, functionally identical on Android) before calling `onDeleteAccount`, which you wire up to your actual API call.
- Shows an inline spinner and disables the row while the delete request is in flight, and surfaces a retry alert on failure.
- Uses `Platform.select` for shadow (iOS) vs. elevation (Android), and respects safe areas on both platforms.
- No third-party dependencies — only `react-native` core.
